// Extract order details and pre-build both emails
const order = $input.first().json.body ?? $input.first().json;
const c = order.customer || {};

const email = (order.email || c.email || '').toLowerCase();
const firstName = c.first_name || (order.shipping_address && order.shipping_address.first_name) || 'there';
const lineItems = order.line_items || [];
const bookTitle = lineItems[0] ? lineItems[0].title : 'your book';
const orderRef = order.order_number || order.name || order.id || '';

const UNSUB = 'https://n8n.opiamanalytics.com/webhook/a42a06d0-14c2-4871-adbe-59b7582306a0?email=' + encodeURIComponent(email);
const REVIEW_LINK = 'https://aalmaram.com'; // REPLACE with the actual review link

function shell(body) {
  return `<!DOCTYPE html><html><body style="margin:0;padding:0;background-color:#f8f5f0;">` +
    `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f8f5f0;"><tr><td align="center" style="padding:32px 16px;">` +
    `<table role="presentation" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;">` +
    `<tr><td style="padding:40px 8px 24px;text-align:center;">` +
    `<div style="font-family:'Playfair Display',Georgia,serif;font-size:22px;letter-spacing:.18em;color:#232f48;">AALMARAM</div>` +
    `<div style="width:48px;height:2px;background:#c6a15b;margin:16px auto 0;font-size:0;">&nbsp;</div>` +
    `</td></tr>` +
    `<tr><td style="font-family:'Nunito',Helvetica,Arial,sans-serif;font-size:16px;line-height:1.7;color:#232f48;padding:8px;">${body}</td></tr>` +
    `<tr><td style="padding:32px 8px;text-align:center;font-family:'Nunito',Helvetica,Arial,sans-serif;font-size:12px;color:#8a8577;">` +
    `Aalmaram Publishing &middot; Kochi, Kerala<br><a href="${UNSUB}" style="color:#8a8577;">Unsubscribe</a>` +
    `</td></tr></table></td></tr></table></body></html>`;
}

const checkinBody =
  `<p>Hello ${firstName},</p>` +
  `<p>It has been a few days since <em>${bookTitle}</em> reached you, and I wanted to ask &mdash; how are you finding it?</p>` +
  `<p>Every copy that leaves Kochi carries a little of Kerala's history with it. I hope it has found a good home on your shelf, and better still, in someone's hands at bedtime.</p>` +
  `<p>If anything about your copy isn't right, just reply to this email and I'll sort it personally.</p>` +
  `<p>Warmly,<br>Nivedith<br><span style="color:#c6a15b;">Aalmaram Publishing</span></p>`;

const reviewBody =
  `<p>Hello ${firstName},</p>` +
  `<p>A small favour. If <em>${bookTitle}</em> has earned a place in your home, a short review helps other families find it.</p>` +
  `<p style="margin:28px 0;text-align:center;"><a href="${REVIEW_LINK}" style="display:inline-block;padding:12px 28px;background:#c6a15b;color:#ffffff;text-decoration:none;font-family:'Nunito',Helvetica,Arial,sans-serif;letter-spacing:.08em;">LEAVE A REVIEW</a></p>` +
  `<p>It takes a minute, and it matters more than you'd think to a small press.</p>` +
  `<p>Thank you,<br>Nivedith</p>`;

return [{
  json: {
    email,
    first_name: firstName,
    book_title: bookTitle,
    order_ref: String(orderRef),
    checkin_subject: `How are you finding ${bookTitle}?`,
    checkin_html: shell(checkinBody),
    review_subject: 'A small favour',
    review_html: shell(reviewBody)
  }
}];

